"""Derive observations from visible code and declared SPEC, never from gold intent."""
import copy
import re
from bj_runtime import Session as Parent,render as old_render,snapshot
from ar_spec import infer,verify,spec_text
from aq_protocol import prompt_ids


CODE_LABEL='Текущий HEX (индекс в начале каждой строки):\n'


def replace_code(text,formula,check):
    # The code block is generated by ha_protocol.prompt, after task/notes.
    # Its exact indexed rows are replaced; user condition and observations remain.
    start=text.rfind(CODE_LABEL);assert start>=0
    at=start+len(CODE_LABEL);end=at
    while end<len(text):
        stop=text.find('\n',end);assert stop>=0
        if not re.fullmatch(r'[0-9A-F]{4}: (?:[0-9A-F]{2})(?: [0-9A-F]{2})*',text[end:stop]):break
        end=stop+1
    assert end>at
    info='Формула текущей программы: '+formula+'.\n'
    info+='Проверка кода по текущей SPEC: '+check['label']+'; '+check['detail']+'.\n'
    info+='MATCH означает совпадение на проверочных входах; понимание русского условия проверяется отдельно.\n'
    return text[:start]+info+text[end:]


class SymbolicSession(Parent):
    tokenizer=None
    def code_observation(self):
        try:
            implied=infer(self.body,self.pool,self.task['angle']);formula=spec_text(implied);supported=True
        except (ValueError,ArithmeticError,KeyError)as e:
            implied=None;formula='UNKNOWN';supported=False
        if self.gate_cache is None:self.gate_cache=verify(self.vm,self.body,self.pool,self.declared_spec,self.checker_inputs)
        result=copy.deepcopy(self.gate_cache);label={'TESTED':'MATCH','FAIL':'MISMATCH'}.get(result['status'],'UNKNOWN')
        detail=str(result.get('cases',0))+' числовых тестов'
        if result['status']=='FAIL':detail+='; '+result.get('reason','FAIL')
        return formula,{'label':label,'detail':detail,'numeric_check':result,'formula_supported':supported,
                       'uses_gold_intent':False,'source':'current program and declared SPEC only'}
    def request(self):
        text=super().request();formula,check=self.code_observation();self.last_symbolic_check=check
        self.pending_symbolic_record=copy.deepcopy(check)
        if check['formula_supported']:return replace_code(text,formula,check)
        # Unsupported code keeps its HEX. Numerical status remains explicitly finite.
        marker='Ассистент: <';assert text.endswith(marker)
        return text[:-len(marker)]+'Формула текущего кода: UNKNOWN. Проверка по SPEC: '+check['label']+'.\n'+marker
    def replan_request(self):
        # Same original code-free review: no program/formula/check leaks into it.
        self.pending_symbolic_record=None
        return super().replan_request()
    def apply_action(self,action,body):
        before=getattr(self,'pending_symbolic_record',None);self.pending_symbolic_record=None
        result=super().apply_action(action,body)
        if before is not None:self.history[-1]['visible_program_check']=before
        return result
